css:
.cols {
  display: flex;
  gap: 32px;
  padding: 24px;
  font-family: system-ui, sans-serif;
  font-size: 18px;
  line-height: 1.5;
}

.col {
  width: 150px;
  margin: 0;
  padding: 12px;
  border: 1px solid #fdba74;
  border-radius: 8px;
}

.anywhere {
  overflow-wrap: anywhere;
}

.hyphenated {
  overflow-wrap: break-word;
  hyphens: auto;
}
